const { createClient } = require('@supabase/supabase-js');

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function createTables() {
  console.log('Creating venue tables...');

  // Create venues table
  const createVenuesTable = `
    CREATE TABLE IF NOT EXISTS public.venues (
      id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
      place_id TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      address TEXT NOT NULL,
      formatted_address TEXT,
      phone TEXT,
      website TEXT,
      rating DECIMAL(2,1),
      reviews_count INTEGER DEFAULT 0,
      price_level INTEGER,
      category TEXT NOT NULL,
      types TEXT[] DEFAULT ARRAY[]::TEXT[],
      business_status TEXT,
      latitude DECIMAL(10, 8),
      longitude DECIMAL(11, 8),
      zip_code TEXT,
      city TEXT,
      state TEXT,
      country TEXT DEFAULT 'US',
      description TEXT,
      photos TEXT[] DEFAULT ARRAY[]::TEXT[],
      opening_hours JSONB,
      accessibility_info TEXT,
      parking_info TEXT,
      party_packages_available BOOLEAN DEFAULT FALSE,
      max_capacity INTEGER,
      age_restrictions TEXT,
      amenities TEXT[] DEFAULT ARRAY[]::TEXT[],
      last_validated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      data_freshness_days INTEGER DEFAULT 30,
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
    );
  `;

  // Create party_venues table
  const createPartyVenuesTable = `
    CREATE TABLE IF NOT EXISTS public.party_venues (
      id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
      party_id UUID REFERENCES public.parties(id) ON DELETE CASCADE NOT NULL,
      venue_id UUID REFERENCES public.venues(id) ON DELETE SET NULL,
      user_id UUID REFERENCES public.users(id) ON DELETE CASCADE NOT NULL,
      custom_name TEXT,
      custom_address TEXT,
      custom_notes TEXT,
      selected_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      is_custom BOOLEAN DEFAULT FALSE,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      UNIQUE(party_id)
    );
  `;

  // Create venue_searches table
  const createVenueSearchesTable = `
    CREATE TABLE IF NOT EXISTS public.venue_searches (
      id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
      zip_code TEXT NOT NULL,
      category TEXT NOT NULL,
      radius_miles INTEGER DEFAULT 20,
      search_query TEXT,
      min_rating DECIMAL(2,1) DEFAULT 0,
      total_results INTEGER DEFAULT 0,
      search_completed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      expires_at TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '7 days'),
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      UNIQUE(zip_code, category, radius_miles, search_query, min_rating)
    );
  `;

  // Create venue_search_results table
  const createVenueSearchResultsTable = `
    CREATE TABLE IF NOT EXISTS public.venue_search_results (
      id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
      search_id UUID REFERENCES public.venue_searches(id) ON DELETE CASCADE NOT NULL,
      venue_id UUID REFERENCES public.venues(id) ON DELETE CASCADE NOT NULL,
      distance_miles DECIMAL(5,2),
      search_rank INTEGER,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      UNIQUE(search_id, venue_id)
    );
  `;

  try {
    console.log('Creating venues table...');
    const { error: error1 } = await supabase.rpc('exec', { sql: createVenuesTable });
    if (error1) console.log('venues error:', error1.message);
    else console.log('✓ venues table created');

    console.log('Creating party_venues table...');
    const { error: error2 } = await supabase.rpc('exec', { sql: createPartyVenuesTable });
    if (error2) console.log('party_venues error:', error2.message);
    else console.log('✓ party_venues table created');

    console.log('Creating venue_searches table...');
    const { error: error3 } = await supabase.rpc('exec', { sql: createVenueSearchesTable });
    if (error3) console.log('venue_searches error:', error3.message);
    else console.log('✓ venue_searches table created');

    console.log('Creating venue_search_results table...');
    const { error: error4 } = await supabase.rpc('exec', { sql: createVenueSearchResultsTable });
    if (error4) console.log('venue_search_results error:', error4.message);
    else console.log('✓ venue_search_results table created');

  } catch (error) {
    console.error('Failed to create tables:', error.message);
  }
}

createTables();
